# Helper to process raw text to CSV lines
def clean_data(raw):
    lines = []
    for line in raw.strip().split('\n'):
        parts = [p.strip() for p in line.split('\t')]
        if any(parts):
            lines.append(','.join(parts))
    return lines

# Headers
pitching_header = "#,Name,Team,K/9 K/9 - Strikeouts per 9 Innings ((SO*9)/IP),BB/9 BB/9 - Walks per 9 Innings ((BB*9)/IP),K/BB K/BB - Strikeout to Walk Ratio (SO/BB),HR/9 HR/9 - Home Runs per 9 Innings ((HR*9)/IP),K% K% - Strikeout Percentage (SO/TBF),BB% BB% - Walk Percentage (BB/TBF),K-BB% K-BB% - The difference between strikeout percentage and walk percentage,AVG AVG - Batting Average Against,WHIP WHIP - Walks + Hits divided by Innings Pitched,BABIP BABIP - Batting Average on Balls in Play,LOB% LOB% - Left on Base Percentage,ERA- ERA- - ERA adjusted for park and league where 100 is average and lower is better,FIP- FIP- - FIP adjusted for park and league where 100 is average and lower is better,xFIP- xFIP- - xFIP adjusted by league where 100 is average and lower is better,ERA ERA - Earned Run Average ((ER*9)/IP),FIP FIP - Fielder Independent Pitching on an ERA scale,E-F,xFIP xFIP - Expected Fielder Independent Pitching where Home Runs are calculated as 10.5% of Fly Balls induced,SIERA SIERA - Skill Interactive ERA"
batting_header = "#,Name,Team,PA,BB%,K%,BB/K,AVG,OBP,SLG,OPS,ISO,Spd,BABIP,UBR,wGDP,XBR,wSB,wRC,wRAA,wOBA,wRC+"

# Write to a clean temporary file and then append
# Note: Appending to the existing file works because the parser overwrites the section with the last one encountered.
with open('/Users/danielreiss/Desktop/Antigravity/MLB/data/MLB Stats', 'a') as f:
    f.write('\nPitching Advanced,,,,,,,,,,,,,,,,,,,,,\n')
    f.write(pitching_header + '\n')
    for line in clean_data(starters_raw):
        f.write(line + '\n')
    for line in clean_data(relievers_raw):
        f.write(line + '\n')
    
    f.write('\nBatting Advanced,,,,,,,,,,,,,,,,,,,,,\n')
    f.write(batting_header + '\n')
    for line in clean_data(batting_raw):
        f.write(line + '\n')

print("SUCCESS: Combined Pitching (Starters + Relievers) and Batting Advanced stats synced to MLB Stats.")